/// One raw match row for `repeated_concern_matches` below (ADR-0082):
/// unlike `risk_signals` (obligations.rs), "the same risk in another
/// meeting" is inherently a cross-row comparison, so this queries
/// `candidate_projection`/`embeddings` directly rather than taking
/// already-fetched rows as parameters.
#[derive(Debug, Clone, FromRow)]
struct RepeatedConcernMatch {
    candidate_id: Uuid,
    matched_candidate_id: Uuid,
    matched_meeting_id: Uuid,
    matched_meeting_text: String,
}

/// ADR-0082: a `risk` candidate matches another `risk` candidate from a
/// *different* meeting (`source_fragments.source_id`) whose source
/// fragment embedding is within cosine similarity >=
/// `REPEATED_CONCERN_SIMILARITY_THRESHOLD` -- the same
/// `1 - (embedding <=> embedding)` expression
/// `graph::source_fragment::search_source_fragments` already uses, as a
/// self-join instead of an ad hoc query embed. Excludes either side being
/// already promoted (a real, tracked Obligation is this repo's existing
/// proxy for "mitigation") or rejected ("not a genuine management
/// object", PRODUCT-SPEC.md SS6). Symmetric: if A matches B, a separate
/// row also reports B matching A.
async fn repeated_concern_matches(pool: &PgPool) -> Result<Vec<RepeatedConcernMatch>, sqlx::Error> {
    sqlx::query_as(
        "SELECT a.candidate_id AS candidate_id, \
                b.candidate_id AS matched_candidate_id, \
                sfb.source_id AS matched_meeting_id, \
                nb.canonical_text AS matched_meeting_text \
         FROM candidate_projection a \
         JOIN source_fragments sfa ON sfa.id = a.source_fragment_id \
         JOIN embeddings ea ON ea.entity_type = 'source_fragment' AND ea.entity_id = sfa.id \
         JOIN embeddings eb ON eb.entity_type = 'source_fragment' \
         JOIN source_fragments sfb ON sfb.id = eb.entity_id \
         JOIN candidate_projection b ON b.source_fragment_id = sfb.id \
         JOIN nodes nb ON nb.id = sfb.source_id \
         WHERE a.candidate_type = 'risk' \
           AND b.candidate_type = 'risk' \
           AND a.candidate_id != b.candidate_id \
           AND a.validation_state != 'rejected' \
           AND b.validation_state != 'rejected' \
           AND a.promoted_obligation_id IS NULL \
           AND b.promoted_obligation_id IS NULL \
           AND sfa.source_id != sfb.source_id \
           AND (1 - (ea.embedding <=> eb.embedding)) >= $1",
    )
    .bind(REPEATED_CONCERN_SIMILARITY_THRESHOLD)
    .fetch_all(pool)
    .await
}

/// Groups raw match rows by the flagged candidate, one explanation entry
/// per matched meeting (ADR-0082's "explanation required" shape,
/// PRODUCT-SPEC.md SS7.1).
fn repeated_concern_by_candidate(
    matches: &[RepeatedConcernMatch],
) -> HashMap<Uuid, Vec<JsonValue>> {
    let mut grouped: HashMap<Uuid, Vec<JsonValue>> = HashMap::new();
    for entry in matches {
        grouped.entry(entry.candidate_id).or_default().push(json!({
            "candidate_id": entry.matched_candidate_id,
            "meeting_id": entry.matched_meeting_id,
            "explanation": format!(
                "Also raised as a risk in \"{}\", not yet promoted or rejected there either.",
                entry.matched_meeting_text
            ),
        }));
    }
    grouped
}

/// Reads the current `candidate_projection` rows, joined read-only against
/// the immutable `source_fragments` table for evidence (ADR-0013/ADR-0015).
/// Never writes. `limit`/`offset` of `None` fetch every row unchanged
/// (ADR-0059); a given `limit` is clamped to `[1, MAX_LIST_LIMIT]` rather
/// than rejected, matching ADR-0049's audit-limit precedent. Also attaches
/// `repeated_concern` (ADR-0082), computed across every `risk` candidate,
/// not just this page, so a match is never missed by pagination.
pub(super) async fn list_candidates(
    State(pool): State<PgPool>,
    Query(params): Query<ListQuery>,
) -> Result<Json<JsonValue>, (axum::http::StatusCode, String)> {
    let (limit, offset) = clamp_list_params(&params);
    let rows: Vec<CandidateWithSource> = sqlx::query_as(
        "SELECT cp.candidate_id, cp.candidate_type, cp.statement, cp.validation_state, cp.confidence, \
                cp.source_fragment_id, cp.promoted_obligation_id, sf.text AS source_text, sf.speaker \
         FROM candidate_projection cp \
         LEFT JOIN source_fragments sf ON sf.id = cp.source_fragment_id \
         ORDER BY cp.confidence DESC NULLS LAST, cp.candidate_id \
         LIMIT $1 OFFSET $2",
    )
    .bind(limit)
    .bind(offset)
    .fetch_all(&pool)
    .await
    .map_err(|error| (axum::http::StatusCode::INTERNAL_SERVER_ERROR, error.to_string()))?;

    let matches = repeated_concern_matches(&pool)
        .await
        .map_err(|error| (axum::http::StatusCode::INTERNAL_SERVER_ERROR, error.to_string()))?;
    let grouped = repeated_concern_by_candidate(&matches);

    Ok(Json(json!(rows
        .iter()
        .map(|row| {
            let mut value = candidate_with_source_json(row);
            value["repeated_concern"] = json!(grouped
                .get(&row.candidate_id)
                .cloned()
                .unwrap_or_default());
            value
        })
        .collect::<Vec<_>>())))
}

/// Shared body for accept/reject (ADR-0024): both are a plain state
/// transition with no field changes, differing only in the event type.
/// `409` when the candidate isn't currently in the `candidate` state stops
/// a stale UI from double-transitioning something already resolved.
async fn transition_one(
    pool: &PgPool,
    id: Uuid,
    event_type: &'static str,
) -> Result<(), (axum::http::StatusCode, String)> {
    let current: CandidateWithSource = sqlx::query_as(
        "SELECT cp.candidate_id, cp.candidate_type, cp.statement, cp.validation_state, cp.confidence, \
                cp.source_fragment_id, cp.promoted_obligation_id, sf.text AS source_text, sf.speaker \
         FROM candidate_projection cp \
         LEFT JOIN source_fragments sf ON sf.id = cp.source_fragment_id \
         WHERE cp.candidate_id = $1",
    )
    .bind(id)
    .fetch_one(pool)
    .await
    .map_err(|error| match error {
        sqlx::Error::RowNotFound => (axum::http::StatusCode::NOT_FOUND, "candidate not found".to_string()),
        other => (axum::http::StatusCode::INTERNAL_SERVER_ERROR, other.to_string()),
    })?;

    if current.validation_state != "candidate" {
        return Err((
            axum::http::StatusCode::CONFLICT,
            format!(
                "candidate is already \"{}\", not \"candidate\"",
                current.validation_state
            ),
        ));
    }

    // ADR-0038: the state-change event and its audit row commit atomically --
    // a failure between the two can never leave the action un-audited.
    let action = if event_type == "accepted" {
        "candidate_accepted"
    } else {
        "candidate_rejected"
    };
    let mut tx = pool.begin().await.map_err(|error| {
        (
            axum::http::StatusCode::INTERNAL_SERVER_ERROR,
            error.to_string(),
        )
    })?;
    extraction::transition_candidate(&mut *tx, id, event_type, json!({}))
        .await
        .map_err(|error| {
            (
                axum::http::StatusCode::INTERNAL_SERVER_ERROR,
                error.to_string(),
            )
        })?;
    audit::record(
        &mut *tx,
        "local-operator",
        action,
        Some(json!({"validation_state": current.validation_state})),
        Some(json!({"validation_state": event_type})),
        "http_api",
        "allowed",
    )
    .await
    .map_err(|error| {
        (
            axum::http::StatusCode::INTERNAL_SERVER_ERROR,
            error.to_string(),
        )
    })?;
    tx.commit().await.map_err(|error| {
        (
            axum::http::StatusCode::INTERNAL_SERVER_ERROR,
            error.to_string(),
        )
    })?;

    Ok(())
}

async fn transition_candidate_route(
    pool: &PgPool,
    id: Uuid,
    event_type: &'static str,
) -> Result<Json<JsonValue>, (axum::http::StatusCode, String)> {
    transition_one(pool, id, event_type).await?;

    extraction::rebuild_candidate_projection(pool)
        .await
        .map_err(|error| {
            (
                axum::http::StatusCode::INTERNAL_SERVER_ERROR,
                error.to_string(),
            )
        })?;

    let updated: CandidateWithSource = sqlx::query_as(
        "SELECT cp.candidate_id, cp.candidate_type, cp.statement, cp.validation_state, cp.confidence, \
                cp.source_fragment_id, cp.promoted_obligation_id, sf.text AS source_text, sf.speaker \
         FROM candidate_projection cp \
         LEFT JOIN source_fragments sf ON sf.id = cp.source_fragment_id \
         WHERE cp.candidate_id = $1",
    )
    .bind(id)
    .fetch_one(pool)
    .await
    .map_err(|error| (axum::http::StatusCode::INTERNAL_SERVER_ERROR, error.to_string()))?;

    Ok(Json(candidate_with_source_json(&updated)))
}

/// Accepts a candidate still in the `candidate` state (ADR-0024). Plain
/// accept, no field changes; use a future correction control for edits.
pub(super) async fn accept_candidate(
    State(pool): State<PgPool>,
    Path(id): Path<Uuid>,
) -> Result<Json<JsonValue>, (axum::http::StatusCode, String)> {
    transition_candidate_route(&pool, id, "accepted").await
}

/// Rejects a candidate still in the `candidate` state (ADR-0024).
pub(super) async fn reject_candidate(
    State(pool): State<PgPool>,
    Path(id): Path<Uuid>,
) -> Result<Json<JsonValue>, (axum::http::StatusCode, String)> {
    transition_candidate_route(&pool, id, "rejected").await
}

#[derive(Debug, Deserialize)]
pub(super) struct BatchTransitionRequest {
    candidate_ids: Vec<Uuid>,
    action: String,
}

/// Transitions up to 200 candidates in one request (ADR-0076). Each
/// candidate keeps the single-item route's state check and atomic event/audit
/// transaction; projection rebuilding happens once after the batch.
pub(super) async fn batch_transition_candidates(
    State(pool): State<PgPool>,
    Json(request): Json<BatchTransitionRequest>,
) -> Result<Json<JsonValue>, (axum::http::StatusCode, String)> {
    validate_batch_ids(&request.candidate_ids)?;

    let event_type = match request.action.as_str() {
        "accept" => "accepted",
        "reject" => "rejected",
        _ => {
            return Err((
                axum::http::StatusCode::BAD_REQUEST,
                "action must be \"accept\" or \"reject\"".to_string(),
            ));
        }
    };

    let mut updated_ids = Vec::new();
    let mut errors = Vec::new();
    for candidate_id in &request.candidate_ids {
        match transition_one(&pool, *candidate_id, event_type).await {
            Ok(()) => updated_ids.push(*candidate_id),
            Err((_, message)) => {
                errors.push(json!({"candidate_id": candidate_id, "error": message}))
            }
        }
    }

    extraction::rebuild_candidate_projection(&pool)
        .await
        .map_err(|error| {
            (
                axum::http::StatusCode::INTERNAL_SERVER_ERROR,
                error.to_string(),
            )
        })?;

    let updated: Vec<CandidateWithSource> = if updated_ids.is_empty() {
        Vec::new()
    } else {
        sqlx::query_as(
            "SELECT cp.candidate_id, cp.candidate_type, cp.statement, cp.validation_state, cp.confidence, \
                    cp.source_fragment_id, cp.promoted_obligation_id, sf.text AS source_text, sf.speaker \
             FROM candidate_projection cp \
             LEFT JOIN source_fragments sf ON sf.id = cp.source_fragment_id \
             WHERE cp.candidate_id = ANY($1) \
             ORDER BY cp.candidate_id",
        )
        .bind(&updated_ids)
        .fetch_all(&pool)
        .await
        .map_err(|error| {
            (
                axum::http::StatusCode::INTERNAL_SERVER_ERROR,
                error.to_string(),
            )
        })?
    };

    Ok(Json(json!({
        "updated": updated
            .iter()
            .map(candidate_with_source_json)
            .collect::<Vec<_>>(),
        "errors": errors,
    })))
}

#[derive(Debug, Deserialize)]
pub(super) struct CorrectCandidateRequest {
    candidate_type: Option<String>,
    statement: Option<String>,
}

/// Corrects a candidate still in the `candidate` state (ADR-0045): edits
/// `candidate_type` and/or `statement` before transitioning to `corrected`,
/// a distinct outcome from `accepted` (PRODUCT-SPEC.md ┬º6.4) that still
/// promotes exactly like `accepted` does. At least one field must actually
/// change, or the request is rejected as a meaningless correction rather
/// than a silent no-op event.
pub(super) async fn correct_candidate(
    State(pool): State<PgPool>,
    Path(id): Path<Uuid>,
    Json(body): Json<CorrectCandidateRequest>,
) -> Result<Json<JsonValue>, (axum::http::StatusCode, String)> {
    let current: CandidateWithSource = sqlx::query_as(
        "SELECT cp.candidate_id, cp.candidate_type, cp.statement, cp.validation_state, cp.confidence, \
                cp.source_fragment_id, cp.promoted_obligation_id, sf.text AS source_text, sf.speaker \
         FROM candidate_projection cp \
         LEFT JOIN source_fragments sf ON sf.id = cp.source_fragment_id \
         WHERE cp.candidate_id = $1",
    )
    .bind(id)
    .fetch_one(&pool)
    .await
    .map_err(|error| match error {
        sqlx::Error::RowNotFound => (axum::http::StatusCode::NOT_FOUND, "candidate not found".to_string()),
        other => (axum::http::StatusCode::INTERNAL_SERVER_ERROR, other.to_string()),
    })?;

    if current.validation_state != "candidate" {
        return Err((
            axum::http::StatusCode::CONFLICT,
            format!(
                "candidate is already \"{}\", not \"candidate\"",
                current.validation_state
            ),
        ));
    }

    if let Some(candidate_type) = &body.candidate_type {
        if !extraction::ALLOWED_CANDIDATE_TYPES.contains(&candidate_type.as_str()) {
            return Err((
                axum::http::StatusCode::BAD_REQUEST,
                format!(
                    "candidate_type must be one of {:?}, got {:?}",
                    extraction::ALLOWED_CANDIDATE_TYPES,
                    candidate_type
                ),
            ));
        }
    }

    let type_changed = body
        .candidate_type
        .as_deref()
        .is_some_and(|value| value != current.candidate_type);
    let statement_changed = body
        .statement
        .as_deref()
        .is_some_and(|value| !value.trim().is_empty() && value != current.statement);
    if !type_changed && !statement_changed {
        return Err((
            axum::http::StatusCode::BAD_REQUEST,
            "a correction must actually change candidate_type or statement".to_string(),
        ));
    }

    let mut payload = serde_json::Map::new();
    if type_changed {
        payload.insert("candidate_type".to_string(), json!(body.candidate_type));
    }
    if statement_changed {
        payload.insert("statement".to_string(), json!(body.statement));
    }

    // ADR-0038: the correction event and its audit row commit atomically.
    let mut tx = pool.begin().await.map_err(|error| {
        (
            axum::http::StatusCode::INTERNAL_SERVER_ERROR,
            error.to_string(),
        )
    })?;
    extraction::transition_candidate(
        &mut *tx,
        id,
        "corrected",
        JsonValue::Object(payload.clone()),
    )
    .await
    .map_err(|error| {
        (
            axum::http::StatusCode::INTERNAL_SERVER_ERROR,
            error.to_string(),
        )
    })?;
    audit::record(
        &mut *tx,
        "local-operator",
        "candidate_corrected",
        Some(json!({"candidate_type": current.candidate_type, "statement": current.statement})),
        Some(JsonValue::Object(payload)),
        "http_api",
        "allowed",
    )
    .await
    .map_err(|error| {
        (
            axum::http::StatusCode::INTERNAL_SERVER_ERROR,
            error.to_string(),
        )
    })?;
    tx.commit().await.map_err(|error| {
        (
            axum::http::StatusCode::INTERNAL_SERVER_ERROR,
            error.to_string(),
        )
    })?;

    extraction::rebuild_candidate_projection(&pool)
        .await
        .map_err(|error| {
            (
                axum::http::StatusCode::INTERNAL_SERVER_ERROR,
                error.to_string(),
            )
        })?;

    let updated: CandidateWithSource = sqlx::query_as(
        "SELECT cp.candidate_id, cp.candidate_type, cp.statement, cp.validation_state, cp.confidence, \
                cp.source_fragment_id, cp.promoted_obligation_id, sf.text AS source_text, sf.speaker \
         FROM candidate_projection cp \
         LEFT JOIN source_fragments sf ON sf.id = cp.source_fragment_id \
         WHERE cp.candidate_id = $1",
    )
    .bind(id)
    .fetch_one(&pool)
    .await
    .map_err(|error| (axum::http::StatusCode::INTERNAL_SERVER_ERROR, error.to_string()))?;

    Ok(Json(candidate_with_source_json(&updated)))
}

/// Promotes one accepted/corrected candidate in an atomic transaction.
/// Shared by the single-item route and ADR-0077's batch route so state
/// checks, due-date/owner carry-forward, and auditing cannot drift.
async fn promote_one(pool: &PgPool, id: Uuid) -> Result<Uuid, (axum::http::StatusCode, String)> {
    let current: CandidateWithSource = sqlx::query_as(
        "SELECT cp.candidate_id, cp.candidate_type, cp.statement, cp.validation_state, cp.confidence, \
                cp.source_fragment_id, cp.promoted_obligation_id, sf.text AS source_text, sf.speaker \
         FROM candidate_projection cp \
         LEFT JOIN source_fragments sf ON sf.id = cp.source_fragment_id \
         WHERE cp.candidate_id = $1",
    )
    .bind(id)
    .fetch_one(pool)
    .await
    .map_err(|error| match error {
        sqlx::Error::RowNotFound => (axum::http::StatusCode::NOT_FOUND, "candidate not found".to_string()),
        other => (axum::http::StatusCode::INTERNAL_SERVER_ERROR, other.to_string()),
    })?;

    if current.validation_state != "accepted" && current.validation_state != "corrected" {
        return Err((
            axum::http::StatusCode::CONFLICT,
            format!(
                "candidate is \"{}\", not \"accepted\" or \"corrected\"",
                current.validation_state
            ),
        ));
    }

    let obligation_id = Uuid::new_v4();
    // ADR-0058: a candidate extracted with a stated deadline seeds the new
    // Obligation's soft (advisory) due date; absent one, this is None and the
    // Obligation is dateless exactly as before.
    let due_at = extraction::candidate_extracted_due_at(pool, id)
        .await
        .map_err(|error| {
            (
                axum::http::StatusCode::INTERNAL_SERVER_ERROR,
                error.to_string(),
            )
        })?;
    // ADR-0060: a candidate extracted with a stated owner resolves, by exact
    // case-insensitive name match only, against an existing Person node.
    // No match (including no owner_name at all) creates nothing extra.
    let owner_name = extraction::candidate_extracted_owner_name(pool, id)
        .await
        .map_err(|error| {
            (
                axum::http::StatusCode::INTERNAL_SERVER_ERROR,
                error.to_string(),
            )
        })?;
    let owner_person_id: Option<Uuid> = match &owner_name {
        Some(name) => sqlx::query_scalar("SELECT id FROM nodes WHERE node_type = 'person' AND lower(canonical_text) = lower($1) LIMIT 1")
            .bind(name)
            .fetch_optional(pool)
            .await
            .map_err(|error| (axum::http::StatusCode::INTERNAL_SERVER_ERROR, error.to_string()))?,
        None => None,
    };
    let mut created_payload = serde_json::Map::new();
    created_payload.insert("status".to_string(), json!("open"));
    created_payload.insert(
        "source_fragment_id".to_string(),
        json!(current.source_fragment_id),
    );
    if let Some(due_at) = due_at {
        created_payload.insert("soft_due_at".to_string(), json!(due_at.to_rfc3339()));
    }
    // ADR-0038: the Obligation creation, the candidate's own promoted
    // transition, and the audit row all commit atomically.
    let mut tx = pool.begin().await.map_err(|error| {
        (
            axum::http::StatusCode::INTERNAL_SERVER_ERROR,
            error.to_string(),
        )
    })?;
    obligation::append_event(
        &mut *tx,
        obligation_id,
        obligation::ObligationEventType::Created,
        JsonValue::Object(created_payload),
    )
    .await
    .map_err(|error| {
        (
            axum::http::StatusCode::INTERNAL_SERVER_ERROR,
            error.to_string(),
        )
    })?;

    // ADR-0060: the owns edge commits in the same transaction as the
    // Obligation it names an owner for.
    if let Some(person_id) = owner_person_id {
        graph::create_edge(&mut *tx, person_id, obligation_id, "owns", None)
            .await
            .map_err(|error| {
                (
                    axum::http::StatusCode::INTERNAL_SERVER_ERROR,
                    error.to_string(),
                )
            })?;
    }

    extraction::transition_candidate(
        &mut *tx,
        id,
        "promoted",
        json!({"obligation_id": obligation_id}),
    )
    .await
    .map_err(|error| {
        (
            axum::http::StatusCode::INTERNAL_SERVER_ERROR,
            error.to_string(),
        )
    })?;

    audit::record(
        &mut *tx,
        "local-operator",
        "candidate_promoted",
        Some(json!({"validation_state": current.validation_state})),
        Some(json!({"validation_state": "promoted", "obligation_id": obligation_id})),
        "http_api",
        "allowed",
    )
    .await
    .map_err(|error| {
        (
            axum::http::StatusCode::INTERNAL_SERVER_ERROR,
            error.to_string(),
        )
    })?;
    tx.commit().await.map_err(|error| {
        (
            axum::http::StatusCode::INTERNAL_SERVER_ERROR,
            error.to_string(),
        )
    })?;

    Ok(obligation_id)
}

/// Promotes an `accepted` or `corrected` candidate into a new Obligation
/// (ADR-0027, extended by ADR-0045 to also accept `corrected`). The route's
/// response contract is unchanged by ADR-0077's shared helper.
pub(super) async fn promote_candidate(
    State(pool): State<PgPool>,
    Path(id): Path<Uuid>,
) -> Result<Response, (axum::http::StatusCode, String)> {
    let obligation_id = promote_one(&pool, id).await?;

    obligation::rebuild_projection(&pool)
        .await
        .map_err(|error| {
            (
                axum::http::StatusCode::INTERNAL_SERVER_ERROR,
                error.to_string(),
            )
        })?;
    extraction::rebuild_candidate_projection(&pool)
        .await
        .map_err(|error| {
            (
                axum::http::StatusCode::INTERNAL_SERVER_ERROR,
                error.to_string(),
            )
        })?;

    #[allow(clippy::type_complexity)]
    let (
        obligation_id,
        status,
        updated_at,
        hard_due_at,
        soft_due_at,
        source_fragment_id,
        source_text,
    ): (
        Uuid,
        String,
        chrono::DateTime<chrono::Utc>,
        Option<chrono::DateTime<chrono::Utc>>,
        Option<chrono::DateTime<chrono::Utc>>,
        Option<Uuid>,
        Option<String>,
    ) = sqlx::query_as(
        "SELECT op.obligation_id, op.status, op.updated_at, op.hard_due_at, op.soft_due_at, \
                op.source_fragment_id, sf.text \
         FROM obligation_projection op \
         LEFT JOIN source_fragments sf ON sf.id = op.source_fragment_id \
         WHERE op.obligation_id = $1",
    )
    .bind(obligation_id)
    .fetch_one(&pool)
    .await
    .map_err(|error| {
        (
            axum::http::StatusCode::INTERNAL_SERVER_ERROR,
            error.to_string(),
        )
    })?;

    Ok((
        axum::http::StatusCode::CREATED,
        Json(json!({
            "obligation_id": obligation_id,
            "status": status,
            "updated_at": updated_at.to_rfc3339(),
            "hard_due_at": hard_due_at.map(|value| value.to_rfc3339()),
            "soft_due_at": soft_due_at.map(|value| value.to_rfc3339()),
            "source_fragment_id": source_fragment_id,
            "source_text": source_text,
        })),
    )
        .into_response())
}

#[derive(Debug, Deserialize)]
pub(super) struct BatchPromoteRequest {
    candidate_ids: Vec<Uuid>,
}

/// Promotes up to 200 accepted/corrected candidates (ADR-0077), preserving
/// one atomic transaction per candidate and rebuilding both projections once
/// after the batch. Per-id failures do not discard successful promotions.
pub(super) async fn batch_promote_candidates(
    State(pool): State<PgPool>,
    Json(request): Json<BatchPromoteRequest>,
) -> Result<Json<JsonValue>, (axum::http::StatusCode, String)> {
    validate_batch_ids(&request.candidate_ids)?;

    let mut obligation_ids = Vec::new();
    let mut errors = Vec::new();
    for candidate_id in &request.candidate_ids {
        match promote_one(&pool, *candidate_id).await {
            Ok(obligation_id) => obligation_ids.push(obligation_id),
            Err((_, message)) => {
                errors.push(json!({"candidate_id": candidate_id, "error": message}))
            }
        }
    }

    obligation::rebuild_projection(&pool)
        .await
        .map_err(|error| {
            (
                axum::http::StatusCode::INTERNAL_SERVER_ERROR,
                error.to_string(),
            )
        })?;
    extraction::rebuild_candidate_projection(&pool)
        .await
        .map_err(|error| {
            (
                axum::http::StatusCode::INTERNAL_SERVER_ERROR,
                error.to_string(),
            )
        })?;

    #[derive(Debug, FromRow)]
    struct PromotedObligation {
        obligation_id: Uuid,
        status: String,
        updated_at: chrono::DateTime<chrono::Utc>,
        hard_due_at: Option<chrono::DateTime<chrono::Utc>>,
        soft_due_at: Option<chrono::DateTime<chrono::Utc>>,
        source_fragment_id: Option<Uuid>,
        source_text: Option<String>,
    }

    let promoted: Vec<PromotedObligation> = if obligation_ids.is_empty() {
        Vec::new()
    } else {
        sqlx::query_as(
            "SELECT op.obligation_id, op.status, op.updated_at, op.hard_due_at, op.soft_due_at, \
                    op.source_fragment_id, sf.text AS source_text \
             FROM obligation_projection op \
             LEFT JOIN source_fragments sf ON sf.id = op.source_fragment_id \
             WHERE op.obligation_id = ANY($1) \
             ORDER BY op.obligation_id",
        )
        .bind(&obligation_ids)
        .fetch_all(&pool)
        .await
        .map_err(|error| {
            (
                axum::http::StatusCode::INTERNAL_SERVER_ERROR,
                error.to_string(),
            )
        })?
    };

    Ok(Json(json!({
        "promoted": promoted
            .iter()
            .map(|row| json!({
                "obligation_id": row.obligation_id,
                "status": row.status,
                "updated_at": row.updated_at.to_rfc3339(),
                "hard_due_at": row.hard_due_at.map(|value| value.to_rfc3339()),
                "soft_due_at": row.soft_due_at.map(|value| value.to_rfc3339()),
                "source_fragment_id": row.source_fragment_id,
                "source_text": row.source_text,
            }))
            .collect::<Vec<_>>(),
        "errors": errors,
    })))
}

/// Triggers extraction for one named source fragment (ADR-0013): explicit
/// and synchronous, never automatic on ingestion. Translates the model
/// adapter's typed errors into HTTP statuses instead of panicking.
pub(super) async fn extract_source_fragment(
    State(pool): State<PgPool>,
    Path(id): Path<Uuid>,
) -> Result<Response, (axum::http::StatusCode, String)> {
    let fragment = graph::get_source_fragment(&pool, id)
        .await
        .map_err(|error| match error {
            sqlx::Error::RowNotFound => (
                axum::http::StatusCode::NOT_FOUND,
                "source fragment not found".to_string(),
            ),
            other => (
                axum::http::StatusCode::INTERNAL_SERVER_ERROR,
                other.to_string(),
            ),
        })?;

    let Some(config) = ModelConfig::from_env() else {
        return Err((
            axum::http::StatusCode::SERVICE_UNAVAILABLE,
            "RINGMASTER_LLM_URL is not set; extraction is disabled".to_string(),
        ));
    };

    match extraction::extract_candidate_via_model(
        &pool,
        &config,
        fragment.id,
        &fragment.text,
        chrono::Utc::now(),
    )
    .await
    {
        Ok(Some(candidate_id)) => {
            extraction::rebuild_candidate_projection(&pool)
                .await
                .map_err(|error| {
                    (
                        axum::http::StatusCode::INTERNAL_SERVER_ERROR,
                        error.to_string(),
                    )
                })?;
            let row: CandidateProjection = sqlx::query_as(
                "SELECT candidate_id, candidate_type, statement, validation_state, confidence FROM candidate_projection WHERE candidate_id = $1",
            )
            .bind(candidate_id)
            .fetch_one(&pool)
            .await
            .map_err(|error| (axum::http::StatusCode::INTERNAL_SERVER_ERROR, error.to_string()))?;
            Ok((axum::http::StatusCode::CREATED, Json(candidate_json(&row))).into_response())
        }
        Ok(None) => Ok(axum::http::StatusCode::NO_CONTENT.into_response()),
        Err(ModelExtractionError::Model(error)) => Err((
            axum::http::StatusCode::SERVICE_UNAVAILABLE,
            error.to_string(),
        )),
        Err(other) => Err((
            axum::http::StatusCode::INTERNAL_SERVER_ERROR,
            other.to_string(),
        )),
    }
}

